@IsTest private class ArgumentShapeObservation48 {
 @IsTest static void SCALAR_CONTROLS() {
  Map<String,Object> payload=new Map<String,Object>();
  OwnedArgumentProvider39 provider=new OwnedArgumentProvider39();
  OwnedArgumentTarget34 target=(OwnedArgumentTarget34)Test.createStub(OwnedArgumentTarget34.class,provider);
  Account record=new Account(Name='Owned shape');
  payload.put('scalar',target.inspect(record));
  payload.put('list',target.inspect(new List<SObject>{record}));
  payload.put('empty',target.inspect(new List<SObject>()));
  payload.put('nullValue',target.inspect(null));
  payload.put('providerCalls',provider.calls.size());
  List<Integer> arities=new List<Integer>();for(Map<String,Object> row:provider.calls)arities.add((Integer)row.get('arity'));
  payload.put('arities',arities);
  System.assertEquals('STUB_ARGUMENT_OBSERVATION',JSON.serialize(payload));
 }
 @IsTest static void WHOLE_LIST() {
  OwnedArgumentProvider39 provider=new OwnedArgumentProvider39();
  OwnedArgumentTarget34 target=(OwnedArgumentTarget34)Test.createStub(OwnedArgumentTarget34.class,provider);
  List<SObject> records=new List<SObject>{new Account(Name='Owned shape')};
  target.write(records);
  Map<String,Object> payload=new Map<String,Object>{'calls'=>provider.calls,'originalSize'=>records.size()};
  System.assertEquals('STUB_ARGUMENT_OBSERVATION',JSON.serialize(payload));
 }
 @IsTest static void PLACEHOLDER_LIST() {
  OwnedArgumentProvider39 provider=new OwnedArgumentProvider39();
  OwnedArgumentTarget34 target=(OwnedArgumentTarget34)Test.createStub(OwnedArgumentTarget34.class,provider);
  target.write(new List<SObject>{null});
  Map<String,Object> payload=new Map<String,Object>{'calls'=>provider.calls};
  System.assertEquals('STUB_ARGUMENT_OBSERVATION',JSON.serialize(payload));
 }
}

