public class OwnedArgumentProvider39 implements System.StubProvider {
 public List<Map<String,Object>> calls=new List<Map<String,Object>>();
 public Object handleMethodCall(Object receiver,String member,Type resultType,List<Type> parameterTypes,List<String> parameterNames,List<Object> arguments) {
  Object value=arguments[0];
  Map<String,Object> row=new Map<String,Object>{'member'=>member,'arity'=>arguments.size(),'declaredType'=>parameterTypes[0].getName(),'nullArgument'=>value==null,'scalarMatch'=>OwnedScalarGuard37.matches(value),'isList'=>value instanceof List<SObject>};
  if(value instanceof List<SObject>) {
   List<SObject> records=(List<SObject>)value;row.put('listSize',records.size());
   if(!records.isEmpty()){row.put('firstNull',records[0]==null);row.put('firstScalarMatch',OwnedScalarGuard37.matches(records[0]));}
  }
  calls.add(row);
  if(member=='inspect')return OwnedScalarGuard37.matches(value);
  return null;
 }
}

public virtual class OwnedArgumentTarget34 {
 public virtual Boolean inspect(Object value) {return false;}
 public virtual void write(List<SObject> records) {}
}

